<script setup>
import {ref,computed} from 'vue';
import ChoiceGroup from './ChoiceGroup.vue';
import {grades,subjects,subjectText,weekdays,timeText,validateRequest} from '../domain.mjs';
const props=defineProps({form:Object});
const emit=defineEmits(['submit','about']);
const stage=ref(0),extras=ref(false),validation=ref('');
const names=['学习需求','时间安排','授课与预算'];
const hours=computed(()=>props.form.sessions.reduce((n,g)=>n+(g.options[0].end-g.options[0].start)/60,0));
const range=computed(()=>({'小学':'160–200','初中':'180–220','高中':'220–270','竞赛':'280–330'}[props.form.grade]));
function move(n){stage.value=n;validation.value='';uni.pageScrollTo({scrollTop:0,duration:120});}
function changeDay(s,e){s.day=Number(e.detail.value)+1;s.end=s.start+(s.day>=6?120:60);}
function changeTime(s,e){const [h,m]=e.detail.value.split(':').map(Number);s.start=h*60+m;s.end=s.start+(s.day>=6?120:60);}
function addSession(){props.form.sessions.push({options:[{day:7,start:840,end:960}]});}
function finish(){try{validateRequest(props.form);validation.value='';emit('submit');}catch(e){validation.value=e.message;}}
</script>
<template>
 <view class="request-flow">
  <view class="flow-heading"><text class="kicker">复旦学生 · 家教匹配</text><text class="flow-title">{{['找到适合孩子的同学','把合适的时间留出来','让每一笔费用都清楚'][stage]}}</text><text class="flow-subtitle">{{['从学习需求开始，合适的人慢慢认识。','先定每周课次，每次可选几个备选时间。','上海线下，全国线上。预算包含通勤补贴。'][stage]}}</text></view>
  <view class="flow-steps"><button v-for="(n,i) in names" :key="n" :class="['flow-step',{current:stage===i,done:stage>i}]" @tap="i<stage && move(i)"><text class="step-number">{{stage>i?'✓':`0${i+1}`}}</text><text>{{n}}</text></button></view>
  <view v-if="stage===0" class="stage-content">
   <view class="stage-block"><ChoiceGroup v-model="form.grade" :options="grades" :columns="4" title="孩子目前的学习阶段" /></view>
   <view class="stage-block"><view class="field-header"><text class="field-title">想辅导哪几科？</text><text class="field-meta">可多选 · 已选 {{form.subjects.length}} 科</text></view><ChoiceGroup v-model="form.subjects" :options="subjects" :columns="3" large multiple /></view>
   <view class="flow-footer"><button class="primary-action" @tap="move(1)"><text>下一步，安排时间</text><t-icon name="arrow-right" size="21" /></button><view class="reassurance"><text>先匹配</text><text class="point">·</text><text>再试课</text><text class="point">·</text><text>合适后付服务费</text></view></view>
   <view class="service-note"><text class="service-note-title">认真选，比选得多更重要。</text><text class="service-note-copy">根据科目、时间和预算推荐同学，由你决定邀请谁。</text><button @tap="$emit('about')">了解试课与收费 <t-icon name="chevron-right" size="14" /></button></view>
  </view>
  <view v-else-if="stage===1" class="stage-content">
   <view class="request-summary"><text>{{form.grade}} · {{subjectText(form)}}</text><button @tap="move(0)">修改 <t-icon name="edit" size="14" /></button></view>
   <view class="field-header schedule-heading"><text class="field-title">每周固定课次</text><text class="field-meta">{{form.sessions.length}} 次 · {{hours}} 小时起</text></view>
   <view v-for="(g,gi) in form.sessions" :key="gi" class="lesson-card">
    <view class="lesson-head"><text class="lesson-index">课次 {{String(gi+1).padStart(2,'0')}}</text><button v-if="form.sessions.length>1" class="subtle-action" @tap="form.sessions.splice(gi,1)">删除课次</button></view>
    <view v-for="(s,si) in g.options" :key="si" class="time-option"><view class="time-option-label"><text>{{si?'备选时间':'首选时间'}}</text><button v-if="si" @tap="g.options.splice(si,1)">移除</button></view><view class="time-pickers"><picker :range="weekdays" :value="s.day-1" @change="changeDay(s,$event)"><view class="time-select">{{weekdays[s.day-1]}}<t-icon name="chevron-down" size="15" /></view></picker><picker mode="time" :value="timeText(s.start)" @change="changeTime(s,$event)"><view class="time-select">{{timeText(s.start)}}<t-icon name="chevron-down" size="15" /></view></picker><text class="time-end">至 {{timeText(s.end)}}</text></view></view>
    <button v-if="g.options.length<3" class="add-time" @tap="g.options.push({day:4,start:1140,end:1200})"><t-icon name="add" size="15" /> 添加一个备选时间</button>
   </view>
   <button v-if="form.sessions.length<4" class="secondary-action" @tap="addSession"><t-icon name="add" size="18" /> 每周再加一次课</button>
   <text class="form-hint">平日晚间 1 小时，周末 2 小时。优先由同一位同学完成全部课次，试课统一为 1 小时。</text>
   <view class="flow-footer"><button class="primary-action" @tap="move(2)"><text>下一步，确认预算</text><t-icon name="arrow-right" size="21" /></button><button class="previous-action" @tap="move(0)">返回学习需求</button></view>
  </view>
  <view v-else class="stage-content">
   <view class="request-summary"><text>{{form.grade}} · {{subjectText(form)}} · 每周 {{form.sessions.length}} 次</text><button @tap="move(1)">修改 <t-icon name="edit" size="14" /></button></view>
   <view class="stage-block"><ChoiceGroup v-model="form.mode" :options="['线下','线上','均可']" title="希望怎样上课？" /></view>
   <view v-if="form.mode!=='线上'" class="address-section"><view class="input-line"><text class="input-label">上海 · 大致位置</text><input v-model="form.location" maxlength="40" placeholder="商圈 / 地铁站附近" /></view><view class="input-line"><text class="input-label">距邯郸校区</text><view class="distance-input"><input type="digit" :value="form.distance" @input="form.distance=Number($event.detail.value)" /><text>km</text></view></view><text class="form-hint">距离为演示手动估算。5 km 内无通勤费，超出后单列往返补贴；无需详细住址。</text></view>
   <view class="stage-block"><view class="field-header"><text class="field-title">每小时预算</text><text class="field-meta">含通勤补贴</text></view><view class="price-inputs"><view><text>¥</text><input type="digit" :value="form.budgetMin/100" @input="form.budgetMin=Math.round(Number($event.detail.value)*100)" /></view><text class="price-dash">—</text><view><text>¥</text><input type="digit" :value="form.budgetMax/100" @input="form.budgetMax=Math.round(Number($event.detail.value)*100)" /></view></view><text class="form-hint">{{form.grade}}参考基础价 {{range}} 元 / 小时。最低 160 元，区间跨度不超过 50 元。</text></view>
   <button class="extras-toggle" @tap="extras=!extras"><view><text>补充孩子的情况</text><text class="field-meta">选填 · 帮助同学提前了解</text></view><t-icon :name="extras?'chevron-up':'chevron-down'" size="18" /></button>
   <view v-if="extras" class="extras"><ChoiceGroup v-model="form.childGender" :options="['女','男']" :columns="2" title="孩子性别" /><view class="stage-block"><text class="field-title">希望合作多久</text><picker :range="['1个月以内','1–3个月','一学期','长期']" @change="form.period=['1个月以内','1–3个月','一学期','长期'][Number($event.detail.value)]"><view class="time-select period-select">{{form.period}}<t-icon name="chevron-down" size="16" /></view></picker></view><view class="stage-block"><ChoiceGroup v-model="form.gender" :options="['无所谓','女','男']" title="同学性别偏好" /></view><textarea v-model="form.notes" maxlength="300" class="notes-input" placeholder="例如：基础比较薄弱，希望先梳理知识点。" /></view>
   <view v-if="validation" class="inline-error" role="alert">{{validation}}</view>
   <view class="flow-footer"><button class="primary-action" @tap="finish"><text>看看合适的同学</text><t-icon name="arrow-right" size="21" /></button><text class="reassurance">仅在本机模拟匹配，不提交真实需求</text><button class="previous-action" @tap="move(1)">返回时间安排</button></view>
  </view>
 </view>
</template>
<style scoped>
.flow-heading{padding:25px 0 24px}.kicker{display:block;color:#50617c;font-size:12px;letter-spacing:1.5px;margin-bottom:10px}.flow-title{display:block;font-size:27px;font-weight:650;letter-spacing:-.9px;line-height:1.5;color:#202733}.flow-subtitle{display:block;font-size:13px;color:#69717d;line-height:1.8;margin-top:7px}.flow-steps{display:flex;border-bottom:1px solid #e6e8ed;gap:15px;margin-bottom:27px}.flow-step{background:none;flex:1;margin:0;padding:0 0 12px;border:0;border-bottom:2px solid transparent;border-radius:0;display:flex;align-items:center;gap:6px;font-size:12px;line-height:1.4;color:#747d88;min-height:44px;white-space:nowrap}.flow-step.current{color:#2857bc;border-color:#2857bc;font-weight:600}.flow-step.done{color:#363f4d}.step-number{font-size:12px;font-variant-numeric:tabular-nums}.stage-block{margin-bottom:25px}.field-header{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:13px}.field-title{font-size:15px;font-weight:600;color:#252a33;display:block}.field-meta{font-size:12px;color:#727986;font-weight:400}.flow-footer{padding-top:4px}.primary-action,.secondary-action{width:100%;display:flex;justify-content:space-between;align-items:center;margin:0;padding:0 20px;background:#2857bc;color:white;border-radius:14px;min-height:54px;line-height:1.4;font-size:15px;font-weight:600}.secondary-action{justify-content:center;gap:8px;background:#f5f7fa;color:#3e4c62;border:1px solid #e2e6ec;font-size:14px;font-weight:500;min-height:48px;border-radius:12px}.reassurance{display:flex;justify-content:center;align-items:center;gap:10px;color:#69717d;font-size:12px;line-height:1.8;margin-top:13px;text-align:center}.point{color:#adb2ba}.service-note{margin-top:31px;padding-top:23px;border-top:1px solid #e8eaee}.service-note-title{display:block;font-family:'Songti SC','STSong','Noto Serif CJK SC',SimSun,serif;font-size:17px;color:#383c45;letter-spacing:.5px}.service-note-copy{display:block;font-size:12px;line-height:1.9;color:#727986;margin-top:7px;max-width:310px}.service-note button{font-size:12px;display:flex;align-items:center;gap:3px;color:#526684;background:none;padding:0;margin:5px 0 0;line-height:1.4;min-height:44px}.request-summary{display:flex;justify-content:space-between;align-items:center;padding:0 0 13px;border-bottom:1px solid #eceef2;margin-bottom:24px;color:#344052;font-size:13px;gap:10px}.request-summary button{background:none;display:flex;align-items:center;gap:5px;margin:0;padding:0;font-size:12px;color:#69717d;min-height:44px;flex-shrink:0}.schedule-heading{margin-top:24px}.lesson-card{background:#f6f8fb;border:1px solid #e7eaf0;border-radius:16px;padding:0 16px 6px;margin-bottom:14px}.lesson-head{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e3e7ee;min-height:49px}.lesson-index{font-size:12px;letter-spacing:.6px;color:#4c6389}.subtle-action{padding:0;background:none;margin:0;color:#6f7783;font-size:12px;min-height:44px;line-height:1.4}.time-option{margin-top:12px}.time-option-label{display:flex;align-items:center;justify-content:space-between;color:#707b8c;font-size:12px;margin-bottom:8px;min-height:25px}.time-option-label button{background:none;margin:0;padding:0 5px;font-size:12px;color:#6f7783;min-height:44px;line-height:1.4}.time-pickers{display:flex;align-items:center;gap:7px}.time-pickers picker{flex:1;min-width:0}.time-select{display:flex;align-items:center;justify-content:space-between;gap:5px;min-height:46px;border:1px solid #dce2eb;background:white;border-radius:9px;padding:0 11px;font-size:15px}.time-end{font-size:12px;color:#687486;white-space:nowrap}.add-time{padding:0;background:none;margin:5px 0 0;color:#526b91;display:flex;gap:5px;align-items:center;font-size:12px;min-height:44px;line-height:1.4}.form-hint{display:block;font-size:12px;color:#727986;line-height:1.85;margin:11px 0 21px}.previous-action{background:none;color:#6e7785;min-height:44px;font-size:13px;padding:0;margin:12px auto 0;line-height:1.4}.address-section{margin:-4px 0 25px}.input-line{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:57px;border-bottom:1px solid #e8eaee}.input-label{font-size:13px;flex-shrink:0;color:#535e6f}.input-line input{font-size:14px;text-align:right;min-width:0}.distance-input{display:flex;align-items:center;gap:7px;font-size:12px;color:#737c89;max-width:100px}.price-inputs{display:flex;align-items:center;gap:12px}.price-inputs>view{display:flex;align-items:center;flex:1;min-width:0;border-bottom:1px solid #aebace;padding:10px 0 15px;gap:9px}.price-inputs>view>text{font-size:18px;color:#546b8f}.price-inputs input{font-size:29px;font-weight:500;min-width:0;height:36px;font-variant-numeric:tabular-nums}.price-dash{font-size:15px;color:#9ba6b6}.extras-toggle{display:flex;align-items:center;justify-content:space-between;width:100%;text-align:left;padding:16px 0;background:none;border-top:1px solid #e8eaee;border-bottom:1px solid #e8eaee;margin:8px 0 24px;border-radius:0;font-size:14px;line-height:1.7}.extras-toggle .field-meta{display:block}.extras{padding-bottom:22px}.extras .stage-block{margin-top:22px}.period-select{margin-top:12px}.notes-input{background:#f5f7fa;border:1px solid #e3e7ee;border-radius:12px;padding:14px;font-size:14px;width:100%;height:105px;box-sizing:border-box;line-height:1.8}.inline-error{font-size:13px;color:#ac3b31;background:#fff2ee;border-radius:10px;padding:13px;margin-bottom:15px}.request-flow button::after{border:0}.request-flow button:focus-visible{outline:2px solid #2857bc;outline-offset:3px}@media(max-width:350px){.flow-title{font-size:24px}.flow-steps{gap:8px}.flow-step{gap:4px}.time-select{padding:0 7px;font-size:14px}.lesson-card{padding-left:12px;padding-right:12px}}
